      "className": "scene",
      "text": "(물거울이 터진다. 대왕이 왕좌에서 몸을 일으키자 검은 파도가 방 둘레를 감싸고, 삼지창의 결정이 날카롭게 울린다.)",
      "scene": "world-7b",
