      "className": "scene",
      "text": "(호숫가. 소서러스가 마지막 계단을 밟자, 뒤에서 검은 수면이 닫힌다. 구슬의 빛은 잦아들지만 새 지팡이의 결정에는 푸른빛이 남아 있다.)",
