      "className": "scene",
      "text": "(아서가 다친 주민을 데리고 빠져나온다. 파이터가 손을 놓자 큰 가지가 돌바닥에 떨어진다. 나무는 강가 쪽으로 천천히 기울어 멈춘다.)",
      "scene": "silver-bell-village",
      "sceneNumber": 1,
      "location": "은종 마을 · 돌다리 앞",
