      "text": "도망치는 자들 사이에 종지기가 숨어 있었다. 놓쳤다면 기록을 찾는 데 더 오래 걸렸겠지.",
      "scene": "silver-bell-village",
      "sceneNumber": 2,
      "location": "종루 계단 앞",
      "backgroundPath": "assets/story/chapter-8-silver-bell-village-map.webp",
